const D = { scale: 1, energy: .62, density: .55, speed: 1, hue: 260, x: .5, y: .5, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v,a,b) => v<a?a:(v>b?b:v);

// ---- coarse integer grid: scale -> cell size (bigger scale = chunkier, fewer cells) ----
const GW = clp(Math.round(180 / (0.55 + clp(P.scale,0.5,2.6))), 48, 200) | 0;
const GH = clp(Math.round(GW * height / Math.max(1, width)), 32, 200) | 0;
const cells = GW * GH;
const seedI = P.seed | 0;

// ---- Abelian relaxation via a work-stack (queue toppling; exact, Abelian-order-free) ----
function relax(maxOps) {
  const grid = S.grid, glow = S.glow, st = S.stack, cap = st.length;
  let sp = 0;
  for (let idx = 0; idx < cells; idx++) if (grid[idx] >= 4) { if (sp < cap) st[sp++] = idx; }
  let ops = 0;
  while (sp > 0 && ops < maxOps) {
    const idx = st[--sp];
    const h = grid[idx];
    if (h < 4) continue;
    const times = h >> 2;               // topple floor(h/4) times at once (Abelian batch)
    grid[idx] = h - times * 4;
    glow[idx] = 1;                       // mark toppled this pass (avalanche shimmer)
    const y = (idx / GW) | 0;
    const x = idx - y * GW;
    if (x > 0)       { const n = idx - 1;  grid[n] += times; if (grid[n] >= 4 && sp < cap) st[sp++] = n; }
    if (x < GW - 1)  { const n = idx + 1;  grid[n] += times; if (grid[n] >= 4 && sp < cap) st[sp++] = n; }
    if (y > 0)       { const n = idx - GW; grid[n] += times; if (grid[n] >= 4 && sp < cap) st[sp++] = n; }
    if (y < GH - 1)  { const n = idx + GW; grid[n] += times; if (grid[n] >= 4 && sp < cap) st[sp++] = n; }
    ops++;                               // grains that fall off-grid are lost (open sinks)
  }
}

// ---- (re)build + pre-grow the pile on size / seed change (start with a real mandala) ----
const key = GW + 'x' + GH + '_' + seedI;
if (!S.grid || S.key !== key) {
  S.key = key;
  S.grid = new Int32Array(cells);
  S.glow = new Float32Array(cells);
  S.stack = new Int32Array(cells + 32);
  S.acc = 0; S.lastT = null;
  const fr = i => { const s = Math.sin(i * 127.1 + seedI * 311.7) * 43758.5453; return s - Math.floor(s); };
  const cx = (GW * 0.5) | 0, cy = (GH * 0.5) | 0;
  const init = Math.max(1200, Math.round(cells * 0.5));
  S.grid[cy * GW + cx] += init;
  if (seedI !== 0) {                     // seed > 0: asymmetric secondary sources
    const nsrc = 1 + (fr(1) * 2 | 0);
    for (let k = 0; k < nsrc; k++) {
      const ox = ((fr(k * 3 + 2) - 0.5) * GW * 0.5) | 0, oy = ((fr(k * 3 + 3) - 0.5) * GH * 0.5) | 0;
      const sx = clp(cx + ox, 1, GW - 2) | 0, sy = clp(cy + oy, 1, GH - 2) | 0;
      S.grid[sy * GW + sx] += Math.round(init * (0.25 + fr(k * 3 + 4) * 0.4));
    }
  }
  for (let it = 0; it < 48; it++) { relax(8000000); let any = false; for (let idx = 0; idx < cells; idx++) if (S.grid[idx] >= 4) { any = true; break; } if (!any) break; }
  S.glow.fill(0);
}

// ---- clock -> continuous pour at a slowly-wandering source (K.t motion floor) ----
if (S.lastT == null || K.t < S.lastT || K.t - S.lastT > 0.5) S.lastT = K.t;
const dt = Math.min(0.08, K.t - S.lastT); S.lastT = K.t;
const secF = K.section | 0;
const wob = 0.05 + (secF % 8) / 8 * 0.11;         // wander radius grows across the arc
const ang = K.t * 0.22;
const js = (seedI % 97) * 0.3;
let sx = Math.round(GW * clp(P.x,0,1) + Math.cos(ang + js) * GW * wob + Math.cos(ang * 1.7) * GW * wob * 0.4);
let sy = Math.round(GH * clp(P.y,0,1) + Math.sin(ang * 1.1 + js) * GH * wob + Math.sin(ang * 2.3) * GH * wob * 0.4);
sx = clp(sx, 1, GW - 2) | 0; sy = clp(sy, 1, GH - 2) | 0;
const pourRate = (6 + clp(P.density,0,1) * 130) * (0.5 + K.intensity * 0.9) * (0.4 + clp(P.speed,0,3) * 0.8) * (1 + A.bass * 1.4);
S.acc += pourRate * dt;
let nDrop = S.acc | 0; if (nDrop > 900) nDrop = 900; S.acc -= nDrop;
if (nDrop > 0) S.grid[sy * GW + sx] += nDrop;

// decay avalanche shimmer, then run this frame's toppling
const glow = S.glow;
for (let idx = 0; idx < cells; idx++) glow[idx] *= 0.86;
relax(300000);

// ---- coarse pixel buffer ----
if (!S.g || S.gw !== GW || S.gh !== GH) { S.g = createGraphics(GW, GH); S.g.pixelDensity(1); S.gw = GW; S.gh = GH; }

// ---- exposure with continuous K.t breathing (period ~11s, never re-phases at 8s) ----
const expo = 0.55 + clp(P.energy,0,1) * 0.85 + K.intensity * 0.28 + 0.12 * Math.sin(K.t * 0.55) + A.rms * 0.6 + A.bass * 0.22;
const hueShift = P.hue - 260;
const style = P.style;

// 4-height swatch tables (HSB) for the fill styles
const SPEC  = [[258,0.72,0.22],[300,0.78,0.52],[42,0.88,0.95],[46,0.14,1.0]];
const THERM = [[12,0.85,0.07],[6,1.0,0.55],[30,1.0,0.9],[46,0.30,1.0]];
const COPP  = [[150,0.5,0.12],[158,0.6,0.45],[120,0.35,0.72],[20,0.75,0.8]];
const isThermal = style === 'thermal';
const isCopper = style === 'copper-oxide' || style === 'copper';
const isNeon = style === 'neon-contour' || style === 'neon';
const isTopo = style === 'grayscale-topographic' || style === 'topo' || style === 'grayscale';
const SW = isThermal ? THERM : (isCopper ? COPP : SPEC);

const OUT = [0, 0, 0];
function hsv(o, h, s, v) {
  h = ((h % 360) + 360) % 360; const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, g, b;
  if (h < 60) { r = c; g = x; b = 0; } else if (h < 120) { r = x; g = c; b = 0; } else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; } else if (h < 300) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
  o[0] = (r + m) * 255; o[1] = (g + m) * 255; o[2] = (b + m) * 255;
}

// ---- render heights -> pixels ----
const grid = S.grid;
const g = S.g; g.loadPixels(); const px = g.pixels;
for (let j = 0; j < GH; j++) {
  for (let i = 0; i < GW; i++) {
    const idx = j * GW + i;
    let hc = grid[idx]; if (hc < 0) hc = 0; else if (hc > 3) hc = 3;
    const gl = glow[idx];
    let hh, ss, vv;
    if (isNeon) {                        // ABSTRACT: only height-region boundaries glow (nested squares/diamonds)
      let lvl = -1;
      let rn = hc; if (i < GW - 1) { rn = grid[idx + 1]; rn = rn < 0 ? 0 : (rn > 3 ? 3 : rn); }
      let dn = hc; if (j < GH - 1) { dn = grid[idx + GW]; dn = dn < 0 ? 0 : (dn > 3 ? 3 : dn); }
      if (rn !== hc) lvl = rn > hc ? rn : hc; else if (dn !== hc) lvl = dn > hc ? dn : hc;
      if (lvl >= 0) { hh = (lvl === 1 ? 188 : lvl === 2 ? 312 : 52) + hueShift; ss = 0.9; vv = clp((0.45 + lvl * 0.16) * (0.5 + expo * 0.5) + gl * 0.5, 0, 1.4); }
      else { hh = 250 + hueShift; ss = 0.7; vv = 0.055 + gl * 0.28; }
    } else if (isTopo) {                 // ABSTRACT: grayscale elevation bands + bright contour ridges
      let edge = false;
      let rn = hc; if (i < GW - 1) { rn = grid[idx + 1]; rn = rn < 0 ? 0 : (rn > 3 ? 3 : rn); }
      let dn = hc; if (j < GH - 1) { dn = grid[idx + GW]; dn = dn < 0 ? 0 : (dn > 3 ? 3 : dn); }
      if (rn !== hc || dn !== hc) edge = true;
      let base = 0.12 + hc * 0.25; if (edge) base = base + 0.30;
      hh = 42 + hueShift * 0.12; ss = 0.05; vv = clp(base * (0.6 + expo * 0.4) + gl * 0.3, 0, 1.3);
    } else {                             // FILL: spectral / thermal / copper ramp
      const sw = SW[hc];
      hh = sw[0] + hueShift; ss = sw[1]; vv = sw[2] * expo;
      if (gl > 0.02) { vv = vv + gl * 0.55 * (0.4 + P.energy) + A.treble * gl * 0.4; ss = ss - gl * 0.35; if (ss < 0) ss = 0; }
    }
    hsv(OUT, hh, ss, vv);
    const o = 4 * idx;
    px[o] = OUT[0]; px[o + 1] = OUT[1]; px[o + 2] = OUT[2]; px[o + 3] = 255;
  }
}
g.updatePixels();

// ---- draw (upscale). alpha<100 = translucent for VJ compositing (no bg clear) ----
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.g, 0, 0, width, height);
pop();

// ---- audio reactivity ON TOP of the clk baseline (all-zero during validation) ----
if (A.bass > 0.01 || A.treble > 0.01 || A.rms > 0.01) {
  push(); blendMode(ADD); noStroke();
  fill((P.hue + 24) % 360, 42, 100, A.bass * P.energy * 15);
  rect(0, 0, width, height);
  const cx = width * clp(P.x,0,1), cy = height * clp(P.y,0,1), rr = Math.min(width, height) * (0.18 + A.rms * 0.5);
  fill((P.hue + 46) % 360, 30, 100, A.treble * 20);
  ellipse(cx, cy, rr, rr);
  blendMode(BLEND); pop();
}
